    /** SDK-backed access to a deployed contract. */
    class Client(
        val address: String,
        val web3j: org.web3j.protocol.Web3j,
        val transactionManager: org.web3j.tx.TransactionManager,
    ) {
        /** Submits encoded calldata through the configured transaction manager. */
        fun send(data: String, options: TransactionOptions): org.web3j.protocol.core.methods.response.EthSendTransaction {
            require(options.value.signum() >= 0) { "transaction value must be nonnegative" }
            val response = transactionManager.sendTransaction(
                options.gasPrice, options.gasLimit, address, data, options.value, false,
            )
            if (response.hasError()) throw IllegalStateException(response.error.message)
            return response
        }

        /** Calls the contract at the latest block and returns encoded ABI output. */
        fun call(data: String): String {
            val request = org.web3j.protocol.core.methods.request.Transaction.createEthCallTransaction(
                transactionManager.fromAddress, address, data,
            )
            val response = web3j.ethCall(request, org.web3j.protocol.core.DefaultBlockParameterName.LATEST).send()
            if (response.hasError()) throw IllegalStateException(response.error.message)
            if (response.isReverted) throw IllegalStateException("contract call reverted: ${response.revertReasonEncodedData}")
            return response.value
        }
    }

    private sealed interface AbiLayout {
        val dynamic: Boolean
        val headBytes: Int
        fun read(hex: String, at: Int): Any
    }

    private class AbiAtom(
        override val dynamic: Boolean,
        private val decode: (String, Int) -> Any,
    ) : AbiLayout {
        override val headBytes: Int = 32
        override fun read(hex: String, at: Int): Any = decode(hex, at)
    }

    private class AbiArray(
        private val element: AbiLayout,
        private val fixedSize: Int?,
    ) : AbiLayout {
        override val dynamic: Boolean = fixedSize == null || element.dynamic
        override val headBytes: Int = if (dynamic) 32 else Math.multiplyExact(fixedSize!!, element.headBytes)
        override fun read(hex: String, at: Int): Any {
            val count = fixedSize ?: word(hex, at).intValueExact()
            require(count >= 0 && count <= hex.length / 64) { "array length exceeds ABI data" }
            val base = if (fixedSize == null) Math.addExact(at, 32) else at
            var cursor = base
            return List(count) {
                val value = if (element.dynamic) {
                    element.read(hex, Math.addExact(base, word(hex, cursor).intValueExact()))
                } else {
                    element.read(hex, cursor)
                }
                cursor = Math.addExact(cursor, element.headBytes)
                value
            }
        }
    }

    private class AbiTuple(
        private val fields: List<AbiLayout>,
        private val construct: (List<Any>) -> Any,
    ) : AbiLayout {
        override val dynamic: Boolean = fields.any { it.dynamic }
        override val headBytes: Int = if (dynamic) 32 else fields.fold(0) { size, field -> Math.addExact(size, field.headBytes) }
        override fun read(hex: String, at: Int): Any {
            var cursor = at
            val values = fields.map { field ->
                val value = if (field.dynamic) {
                    field.read(hex, Math.addExact(at, word(hex, cursor).intValueExact()))
                } else {
                    field.read(hex, cursor)
                }
                cursor = Math.addExact(cursor, field.headBytes)
                value
            }
            return construct(values)
        }
    }

    private fun word(hex: String, at: Int): java.math.BigInteger {
        val start = Math.multiplyExact(at, 2)
        require(start >= 0 && start <= hex.length - 64) { "truncated ABI word" }
        return java.math.BigInteger(hex.substring(start, start + 64), 16)
    }

    private fun decodeLayout(data: String, layout: AbiLayout): Any {
        require(data.startsWith("0x") && data.length % 2 == 0) { "invalid ABI hex" }
        return layout.read(data.substring(2), 0)
    }

    @Suppress("UNCHECKED_CAST")
    private fun layoutPackedPosition(): AbiLayout = AbiTuple(listOf(AbiAtom(false) { hex, at -> val decoded = org.web3j.abi.TypeDecoder.decode(hex, Math.multiplyExact(at, 2), Bytes32::class.java); decoded }, AbiAtom(false) { hex, at -> val decoded = org.web3j.abi.TypeDecoder.decode(hex, Math.multiplyExact(at, 2), Uint256::class.java); decoded.value }, AbiAtom(false) { hex, at -> val decoded = org.web3j.abi.TypeDecoder.decode(hex, Math.multiplyExact(at, 2), Uint256::class.java); decoded.value })) { values -> PackedPosition(values[0] as Bytes32, values[1] as BigInteger, values[2] as BigInteger) }

    /** Decodes a single ABI return value of tuple `PackedPosition`. */
    @Suppress("UNCHECKED_CAST")
    fun decodePackedPositionValue(data: String): PackedPosition =
        (decodeLayout(data, AbiTuple(listOf(layoutPackedPosition())) { it }) as List<Any>)[0] as PackedPosition

    /** Type reference for decoding the `PackedPosition` tuple. */
    fun referencePackedPosition(): org.web3j.abi.TypeReference<PackedPosition> =
        object : org.web3j.abi.TypeReference<PackedPosition>(false, listOf(object : org.web3j.abi.TypeReference<Bytes32>() {}, object : org.web3j.abi.TypeReference<Uint256>() {}, object : org.web3j.abi.TypeReference<Uint256>() {})) {}

